import { createComponent } from './utils/createComponent.js';

/**
 * A modal is a container that displays over application content to give
 * critical information or to ask users to complete a task in the middle of a
 * workflow. When the modal opens, users cannot access the application.
 */
const Modal = createComponent({
 tagName: 'now-modal',
 displayName: 'Modal',
 eventMap: {
 onFooterActionClicked: ServiceNowEvents.MODAL.FOOTER_ACTION_CLICKED,
 onOpenedSet: ServiceNowEvents.MODAL.OPENED_SET,
 onResizableEnd: ServiceNowEvents.MODAL.RESIZABLE_END,
 onDomReady: ServiceNowEvents.MODAL.DOM_READY
 }
});

